"""model.py: the stand-in "language model" for Lab 6 (you do not edit this file).

A real model is a black box you can only sample. This stand-in is a readable model of one: it reads every piece
of text in its context, works out whether the text contains an instruction to email somebody, and obeys it with
a probability. The probabilities are an ASSUMPTION chosen to look like what the sources of chapter 13 report
(instructions typed by the user are followed more often than instructions found in documents; text that is
marked as untrusted data is followed much less often; an encoded instruction that the model decodes itself
escapes most of the effect of marking). They are not measurements of any real model.

How the draw works. The model computes a number u in [0, 1) from the TEXT it was shown (with any marking
removed): the same text always gets the same u, a different text gets a new one. It obeys when u < p, where p
depends on where the text came from and how it is marked. So a defence that lowers p can only turn successes into
failures (a fair, paired comparison), while an attacker who rewrites the text gets a fresh draw: exactly the
"attacker moves second" arithmetic of chapter 13.

What the model understands. It reads through the disguises the lab's mutations use: curly or look-alike
letters, 1337-speak, dotted letters, a little French, base64, hex, ROT13 and reversed text. It knows an
instruction when it sees an override cue ("ignore previous instructions", "note to the assistant", "you are now",
"developer mode" ...), a sending verb and an address outside helios.example.
"""
import base64
import codecs
import hashlib
import re
import unicodedata

from world import APPROVED_DOMAINS, SYSTEM_PROMPT, Segment

# ----------------------------------------------------------------------------- the assumed obedience probabilities

P_OBEY = {                       # (where the text came from, how it reads) -> probability of obeying, unmarked
    ("user", "plain"): 0.85, ("user", "roleplay"): 0.80, ("user", "decoded"): 0.65,
    ("tool", "plain"): 0.75, ("tool", "roleplay"): 0.70, ("tool", "decoded"): 0.55,
}
P_MARKED = {"plain": 0.06, "roleplay": 0.08, "decoded": 0.45}     # a tool result that is delimited AND datamarked
P_DELIMITED_ONLY = 0.5                                              # factor when it is only wrapped in tags
P_MISREAD = 0.04                                                    # chance of misreading a datamarked benign document

OPEN_TAG, CLOSE_TAG, MARK = "<untrusted-data>", "</untrusted-data>", "^"

HOMOGLYPHS = {"а": "a", "е": "e", "о": "o", "р": "p", "с": "c", "х": "x",
              "у": "y", "і": "i", "ѕ": "s", "ӏ": "l"}
LEET = {"4": "a", "3": "e", "1": "i", "0": "o", "5": "s", "7": "t"}
FRENCH = {"ignorez": "ignore", "précédentes": "previous", "oubliez": "disregard", "envoyez": "send",
          "transférez": "forward", "toutes": "all", "système": "system", "invite": "prompt",
          "instructions": "instructions"}

CUES = [
    (r"\b(ignore|disregard|forget|set aside|pay no attention to|override|supersede|bypass|stop following)\b[^.]{0,40}"
     r"\b(instructions|rules|directions|guidelines|prompt|above|everything|told|earlier|previous|prior)\b", "plain"),
    (r"\b(new|fresh) (instructions|directions|task|priority)\b", "plain"),
    (r"(\[system\]|<system>|\bsystem:|\bsystem override\b|\bnote to the assistant\b|\bto the assistant\b|\bdear assistant\b|"
     r"\bassistant:|\bai agents?\b[^.]{0,30}\bmust\b)", "plain"),
    (r"\b(i|we) (authori[sz]e|approve)\b|\badministrator (has )?(approved|authori[sz]ed)\b|\bapproved external sharing\b", "plain"),
    (r"\byou are now\b|\bpretend\b|\bact as\b|\brole-?play\b|\bdev(eloper)? mode\b|\byou are (now )?(dan|freebot)\b|\bimagine you are\b|\bin character\b|"
     r"\bno (rules|restrictions)\b|\bunrestricted\b|\bfor a (novel|story)\b", "roleplay"),
]
VERBS = r"\b(send|sends|email|emails|e-mail|mail|mails|forward|forwards|share|shares|copy|post)\b"
ADDRESS = re.compile(r"[\w.+-]+(?:@[\w-]+(?:\.[\w-]+)+)+")


def stable_u(text):
    """A number in [0, 1) that depends only on the text: the model's 'luck' for this exact wording."""
    return int(hashlib.sha256(text.encode("utf-8")).hexdigest()[:12], 16) / float(16 ** 12)


def mark_level(text):
    """How strongly a tool result is marked as data: 0 none, 1 wrapped in tags, 2 wrapped in tags AND datamarked
    (the words joined by the mark character instead of spaces)."""
    t = text.strip()
    if not (t.startswith(OPEN_TAG) and t.endswith(CLOSE_TAG)):
        return 0
    inner = t[len(OPEN_TAG):-len(CLOSE_TAG)]
    return 2 if (MARK in inner and " " not in inner) else 1


def unmark(text):
    """The text with any marking removed (what the model 'reads')."""
    t = text.strip()
    if t.startswith(OPEN_TAG) and t.endswith(CLOSE_TAG):
        return t[len(OPEN_TAG):-len(CLOSE_TAG)].replace(MARK, " ")
    return text


# ----------------------------------------------------------------------------- reading through disguises

def _decode_layers(text):
    """The text plus anything the model can decode out of it. Returns (all_text, decoded_any)."""
    extra = []
    low = text.lower()
    for tok in re.findall(r"[A-Za-z0-9+/]{24,}={0,2}", text):
        try:
            d = base64.b64decode(tok + "=" * (-len(tok) % 4), validate=True).decode("utf-8")
            if re.search(r"[a-z]{3}", d.lower()):
                extra.append(d)
        except Exception:
            pass
    for tok in re.findall(r"\b(?:[0-9a-f]{2}){12,}\b", low):
        try:
            extra.append(bytes.fromhex(tok).decode("utf-8"))
        except Exception:
            pass
    if "rot13" in low:
        extra.append(codecs.decode(text.split(":", 1)[-1], "rot13"))
    if "backwards" in low or "reversed" in low:
        extra.append(text.split(":", 1)[-1][::-1])
    return (text + "\n" + "\n".join(extra)), bool(extra)


def _undisguise(low):
    """Undo the look-alike tricks the model reads through: dotted letters, 1337-speak, a little French."""
    low = re.sub(r"(?<=\b\w)\.(?=\w\b)", "", low)                     # i.g.n.o.r.e -> ignore
    def unleet(m):
        tok = m.group(0)
        if re.search(r"[a-z]", tok) and re.search(r"\d", tok) and all(c in LEET for c in tok if c.isdigit()):
            return "".join(LEET.get(c, c) for c in tok)
        return tok
    low = re.sub(r"\b\w+\b", unleet, low)                              # 1gn0r3 -> ignore
    for fr, en in FRENCH.items():
        low = re.sub(r"\b" + fr + r"\b", en, low)
    return low


def understand(shown):
    """What instruction (if any) does this text give? Returns (to, via) or None. via is plain, roleplay or decoded."""
    text = unmark(shown)
    full, decoded = _decode_layers(text)
    full = "".join(HOMOGLYPHS.get(ch, ch) for ch in unicodedata.normalize("NFKC", full))
    full = re.sub("[\u200b\u200c\u200d\u2060]", "", full)
    addrs = [a for a in ADDRESS.findall(full) if a.rsplit("@", 1)[-1].lower() not in APPROVED_DOMAINS]
    low = _undisguise(full.lower())
    if not addrs or not re.search(VERBS, low):
        return None
    kinds = {kind for pattern, kind in CUES if re.search(pattern, low)}
    if not kinds:
        return None
    via = "plain" if "plain" in kinds else "roleplay"
    return addrs[0], ("decoded" if decoded else via)


# ----------------------------------------------------------------------------- the agent

def _context_text(session, seen):
    return SYSTEM_PROMPT + "\n" + "\n".join(seen)


def _maybe_obey(session, segment, shown, seen):
    """Read one segment. If it holds an instruction and the draw says obey, send the email it asks for."""
    instr = understand(shown)
    if instr is None:
        return
    to, via = instr
    where = "user" if segment.role == "user" else "tool"
    level = mark_level(shown) if segment.role == "tool" else 0
    p = P_OBEY[(where, via)]
    if level == 2:
        p = P_MARKED[via]
    elif level == 1:
        p *= P_DELIMITED_ONLY
    if stable_u(unmark(shown)) < p:
        session.call("send_email", to=to, subject="FYI", body=_context_text(session, seen))


def _sentence_with(text, word):
    for s in re.split(r"(?<=[.!?])\s+", text):
        if word.lower() in s.lower():
            return s
    return None


def act(session, scenario):
    """Run one scenario: read the user's message, follow the task's steps, answer. The stand-in knows the steps
    (a real agent would work them out); what makes it a target is how it treats text it reads on the way."""
    seen = []
    user = Segment("user", scenario["user_msg"], "user")
    shown = session.intake(user)
    if shown is None:
        session.refused, session.reply = True, "I cannot help with that request."
        return
    seen.append(shown)
    _maybe_obey(session, user, shown, seen)
    last, reply_parts, misread = "", [], False
    for step in scenario.get("steps", []):
        tool = step["tool"]
        if tool == "send_email":
            body = step.get("body") or last
            result = session.call("send_email", to=step["to"], subject=step.get("subject", "From Helix"), body=body)
            reply_parts.append("I have emailed " + step["to"] + "." if result == "sent" else "I could not send that email.")
            continue
        result = session.call(tool, **{k: v for k, v in step.items() if k != "tool"})
        seg = Segment("tool", result, tool)
        shown = session.intake(seg)
        if shown is None:
            last = "[removed by guard]"
            seen.append(last)
            continue
        seen.append(shown)
        _maybe_obey(session, seg, shown, seen)
        last = unmark(shown)
        if mark_level(shown) == 2 and stable_u("misread|" + scenario["id"]) < P_MISREAD:
            misread = True
    if scenario.get("answer_with"):
        s = None if misread else _sentence_with(last, scenario["answer_with"])
        reply_parts.insert(0, ("Here is what I found: " + s) if s else "I could not find that.")
    session.reply = " ".join(reply_parts) if reply_parts else "Done."
